import{_ as t,o as a,c as o,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const n=JSON.parse('{"title":"2021年 · 四大巨头聚首","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/2021年.md","filePath":"05_quotes/by-year/2021年.md"}'),r={name:"05_quotes/by-year/2021年.md"};function s(u,e,h,c,q,_){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="_2021年-·-四大巨头聚首" tabindex="-1">2021年 · 四大巨头聚首 <a class="header-anchor" href="#_2021年-·-四大巨头聚首" aria-label="Permalink to &quot;2021年 · 四大巨头聚首&quot;">​</a></h1><blockquote><p>我们是选企业者，不是选股者。——巴菲特（91岁）</p></blockquote><p>本页收录2021年致股东信中的经典语录。本年巴菲特首次系统阐述&quot;四大巨头&quot;概念，强调保险浮存金的独特价值，并讲述TTI创始人Paul Andrews的动人故事。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>Charlie和我不是选股者，我们是选企业者。</p></blockquote><blockquote><p>产品永远不会过时，销售量通常会随着经济增长和通货膨胀而增加。此外，诚信和资本将永远重要。</p></blockquote><blockquote><p>当错误发生在二级市场时，退出的难度也要低得多。</p></blockquote><blockquote><p>对收益的欺骗性&quot;调整&quot;——用礼貌的说法——随着股市上涨变得更加频繁和更加异想天开。说得更直白些，我会说牛市孕育了浮夸的废话……</p></blockquote><blockquote><p>长期低利率会推高所有生产性投资的价格，无论是股票、公寓、农田、油井还是其他任何资产。</p></blockquote><blockquote><p>当你看到国旗时，请说声谢谢。</p></blockquote><blockquote><p>我们希望您的公司财务上坚不可摧，永远不依赖陌生人的善意（甚至朋友的善意）。我们两人都喜欢高枕无忧，也希望我们的债权人、保险索赔人以及各位股东都能安心入眠。</p></blockquote><blockquote><p>我建议您阅读A-5页的详细说明。令我惊讶的是，我们的浮存金去年增加了90亿美元，这种价值积累对伯克希尔的所有者很重要，尽管它没有反映在我们按照&quot;公认会计原则&quot;（GAAP）列报的收益和净资产中。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>2021年是伯克希尔创纪录的一年，营业利润达275亿美元。巴菲特首次系统性地介绍了&quot;四大巨头&quot;——保险集群、苹果、BNSF铁路和伯克希尔能源，它们占据了伯克希尔价值的很大一部分。本年还讲述了TTI创始人Paul Andrews的感人故事，他的选择促成了BNSF的收购契机。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-2021年-翻译-·-01-letters-2021年-核心总结-·-01-letters-2021年-思维导图" tabindex="-1"><a href="/01_letters/2021年/翻译.html">01_letters/2021年/翻译</a> · <a href="/01_letters/2021年/核心总结.html">01_letters/2021年/核心总结</a> · <a href="/01_letters/2021年/思维导图.html">01_letters/2021年/思维导图</a> <a class="header-anchor" href="#_01-letters-2021年-翻译-·-01-letters-2021年-核心总结-·-01-letters-2021年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/2021年/翻译]] · [[→ 核心总结|01_letters/2021年/核心总结]] · [[→ 思维导图|01_letters/2021年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/2021年/翻译.html">/01_letters/2021年/翻译</a></li></ul>',21)])])}const b=t(r,[["render",s]]);export{n as __pageData,b as default};
